datasource db {
  provider = "sqlite"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

model User {
  id       Int       @id @default(autoincrement())
  username String    @unique
  comments Comment[]
}

model Post {
  id       Int       @id @default(autoincrement())
  title    String
  comments Comment[]
}

model Comment {
  id       Int       @id @default(autoincrement())
  content  String
  postId   Int
  post     Post      @relation(fields: [postId], references: [id], onDelete: Cascade)
  authorId Int
  author   User      @relation(fields: [authorId], references: [id], onDelete: Cascade)
  parentId Int?
  parent   Comment?  @relation("CommentToComment", fields: [parentId], references: [id], onDelete: Cascade)
  children Comment[] @relation("CommentToComment")
}

app nestedComments {
  wasp: {
    version: "^0.16.8"
  },
  title: "nested-comments",
  db: {
    seeds: [
      import { devSeed } from "@src/seeds"
    ]
  }
}

route RootRoute { path: "/", to: MainPage }
page MainPage {
  component: import { MainPage } from "@src/MainPage"
}

route PostRoute { path: "/post/:postId", to: PostPage }
page PostPage {
  component: import { PostPage } from "@src/PostPage"
}

query getPosts {
  fn: import { getPosts } from "@src/queries",
  entities: [Post]
}

query getCommentTree {
  fn: import { getCommentTree } from "@src/queries",
  entities: [Post, Comment]
}

action createComment {
  fn: import { createComment } from "@src/actions",
  entities: [Comment, User, Post]
}

action deleteComment {
  fn: import { deleteComment } from "@src/actions",
  entities: [Comment]
}

