export const getPosts = async (args, context) => {
  return context.entities.Post.findMany({
    select: {
      id: true,
      title: true,
    },
    orderBy: {
      id: 'asc',
    },
  });
};

export const getCommentTree = async ({ postId }, context) => {
  const comments = await context.entities.Comment.findMany({
    where: { postId: Number(postId) },
    include: {
      author: {
        select: {
          username: true,
        },
      },
    },
    orderBy: {
      id: 'asc',
    },
  });

  const nodesMap = {};
  const rootNodes = [];

  for (const comment of comments) {
    nodesMap[comment.id] = {
      id: comment.id,
      content: comment.content,
      authorUsername: comment.author.username,
      parentId: comment.parentId,
      children: [],
    };
  }

  for (const comment of comments) {
    const node = nodesMap[comment.id];
    if (comment.parentId === null || comment.parentId === undefined) {
      rootNodes.push(node);
    } else {
      const parentNode = nodesMap[comment.parentId];
      if (parentNode) {
        parentNode.children.push(node);
      } else {
        rootNodes.push(node);
      }
    }
  }

  return rootNodes;
};

export const createComment = async ({ postId, authorUsername, content, parentId }, context) => {
  const user = await context.entities.User.findUnique({
    where: { username: authorUsername },
  });
  if (!user) {
    throw new Error(`User with username "${authorUsername}" not found`);
  }

  const newComment = await context.entities.Comment.create({
    data: {
      content,
      postId: Number(postId),
      authorId: user.id,
      parentId: parentId ? Number(parentId) : null,
    },
  });

  return newComment;
};

const deleteCommentAndDescendants = async (commentId, context) => {
  const children = await context.entities.Comment.findMany({
    where: { parentId: commentId },
    select: { id: true },
  });
  for (const child of children) {
    await deleteCommentAndDescendants(child.id, context);
  }
  await context.entities.Comment.delete({
    where: { id: commentId },
  });
};

export const deleteComment = async ({ commentId }, context) => {
  await deleteCommentAndDescendants(Number(commentId), context);
};
